import 'package:flutter/foundation.dart';

enum TaskFilter { all, active, done }

class Task {
  const Task(this.id, this.title, {this.done = false});
  final String id, title;
  final bool done;
}

class TaskStore extends ChangeNotifier {
  final List<Task> _tasks = [];
  TaskFilter filter = TaskFilter.all;

  List<Task> get visible => switch (filter) {
        TaskFilter.all => List.unmodifiable(_tasks),
        TaskFilter.active => _tasks.where((t) => !t.done).toList(),
        TaskFilter.done => _tasks.where((t) => t.done).toList(),
      };

  void add(String title) => _update(() => _tasks
      .add(Task(DateTime.now().microsecondsSinceEpoch.toString(), title)));
  void toggle(String id) => _update(() {
        final i = _tasks.indexWhere((t) => t.id == id);
        if (i != -1) _tasks[i] = Task(id, _tasks[i].title, done: !_tasks[i].done);
      });
  void setFilter(TaskFilter f) => _update(() => filter = f);
  void _update(VoidCallback change) {
    change();
    notifyListeners(); // every change ends here
  }
}

