class LoginFailed extends LoginState { LoginFailed(this.message); final String message; }

class LoginBloc extends Bloc<LoginEvent, LoginState> {
  LoginBloc(this._sendOtp) : super(LoginIdle()) {
    on<PhoneSubmitted>(_onSubmitted);
  }
  final Future<void> Function(String phone) _sendOtp;
  Future<void> _onSubmitted(PhoneSubmitted e, Emitter<LoginState> emit) async {
    if (!RegExp(r'^09\d{9}$').hasMatch(e.phone)) {
      return emit(LoginFailed('شماره موبایل معتبر نیست'));
    }
    emit(LoginSending());
    try {
      await _sendOtp(e.phone);
      emit(OtpSent(e.phone));
    } catch (_) {
      emit(LoginFailed('ارسال پیامک ناموفق بود، دوباره تلاش کن'));
    }
  }
